  return parseYaml(
    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
  ) as Task;
}

export function writeTask(workspaceRoot: string, featureId: string, task: Task): void {
  writeFileSync(
    taskYamlAbsPath(workspaceRoot, featureId, task.id),
    yamlStringify(task),
    "utf-8",
  );
}

