/**
 * Escalation handler — implements the `escalate` branch of dispatchReviewResult.
 *
 * Responsibilities:
 *   1. POST a structured Slack message to SLACK_WEBHOOK_URL (skip gracefully when unset).
 *   2. Mutate the task YAML: status → blocked, blocked_reason, blocked_suggestion.
 *   3. Emit `task_escalated` (or `escalation_slack_skipped` when Slack is absent).
 */

import { mutateTaskYamlDirect } from "./mutate-task-yaml-direct.js";
import { taskBranchName } from "../paths.js";

const BLOCKED_SUGGESTION = "Human review required — reviewer confidence exhausted or hard CI failure";

export interface EscalationOpts {
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskTitle?: string;
  /** Implementation PR URL reported by the executor (task.pr.url). */
  prUrl?: string;
  /** Escalation reason from reviewer notes. */
  notes?: string;
  /** Reviewer review URL (GitHub review link). */
  reviewUrl?: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

/** Build a Slack Block Kit payload for the escalation message. */
function buildSlackPayload(opts: EscalationOpts): Record<string, unknown> {
  const { featureId, taskId, taskTitle, prUrl, notes, reviewUrl } = opts;
  const title = taskTitle ? `${taskId} — ${taskTitle}` : taskId;
  const prLink = prUrl ? `<${prUrl}|View PR>` : "_not available_";
  const reviewLink = reviewUrl ? `<${reviewUrl}|View review>` : "_not available_";
  const reason = notes ?? "No reviewer notes provided.";

  return {
    text: `[Escalation] Task ${title} requires human review`,
    blocks: [
      {
        type: "header",
        text: { type: "plain_text", text: `🚨 Task escalated: ${title}` },
      },
      {
        type: "section",
        fields: [
          { type: "mrkdwn", text: `*Feature:*\n${featureId}` },
          { type: "mrkdwn", text: `*Task:*\n${taskId}` },
          { type: "mrkdwn", text: `*PR:*\n${prLink}` },
          { type: "mrkdwn", text: `*Review:*\n${reviewLink}` },
        ],
      },
      {
        type: "section",
        text: { type: "mrkdwn", text: `*Escalation reason:*\n${reason}` },
      },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: `*Suggested action:*\n${BLOCKED_SUGGESTION}`,
        },
      },
    ],
  };
}

/**
 * Post an escalation message to Slack.
 * Returns true if the message was sent, false if SLACK_WEBHOOK_URL is unset.
 * Throws on network/HTTP errors so the caller can handle them.
 */
export async function postEscalationSlack(
  opts: EscalationOpts,
  webhookUrl: string,
): Promise<void> {
  const payload = buildSlackPayload(opts);
  const resp = await fetch(webhookUrl, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (!resp.ok) {
    throw new Error(`Slack webhook returned ${resp.status}: ${await resp.text()}`);
  }
}

/**
 * Handle a reviewer `escalate` verdict:
 *   1. Post to Slack if configured.
 *   2. Mutate task YAML to blocked.
 *   3. Emit result event.
 */
export async function handleEscalation(opts: EscalationOpts): Promise<void> {
  const {
    workspaceRoot, featureId, taskId, notes,
    gitAuthorEmail, gitAuthorName, sshKeyPath, emit,
  } = opts;

  const taskBranch = taskBranchName(featureId, taskId);
  const webhookUrl = process.env["SLACK_WEBHOOK_URL"];

  if (webhookUrl) {
    try {
      await postEscalationSlack(opts, webhookUrl);
    } catch (e) {
      emit({
        type: "escalation_slack_failed",
        task_id: taskId,
        feature_id: featureId,
        error: String(e),
      });
    }
  } else {
    emit({ type: "escalation_slack_skipped", task_id: taskId, feature_id: featureId });
  }

  const mutateErr = mutateTaskYamlDirect({
    workspaceRoot,
    featureId,
    taskId,
    taskBranch,
    status: "blocked",
    blockedReason: notes ?? "reviewer_escalated",
    blockedSuggestion: BLOCKED_SUGGESTION,
    logEntry: {
      action: "reviewer_complete",
      by: gitAuthorEmail,
      note: notes ?? "Reviewer escalated — human review required.",
    },
    gitAuthorEmail,
    gitAuthorName,
    sshKeyPath,
    commitMessage: `chore(${taskId}): reviewer → escalated (blocked)`,
  });

  if (mutateErr) {
    emit({
      type: "escalation_mutate_failed",
      task_id: taskId,
      feature_id: featureId,
