31	  broker: CompletionBrokerPort;
32	  /** All workspace roots pulled this cycle — used to locate the task YAML. */
33	  workspaceRoots: string[];
34	  /** Visibility-lock duration for peek-and-lock. Default: 30 000 ms. */
35	  lockMs?: number;
