/**
 * Tests for T2 dispatch controller logic:
 *   1. dispatchReviewResult routing (passed, escalate, unknown, change_requested)
 *   2. findFixableTasks eligibility
 *   3. findReviewableTasks eligibility
 *   4. dispatchExecutorResult max-turns retry
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { stringify as yamlStringify } from "yaml";
import { spawnSync } from "node:child_process";
import type { Task } from "../src/types/task.js";

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "ctrl-feature";
const TASK_ID = "T1";
const MGMT_GITHUB = "https://github.com/testorg/mgmt-repo";

function makeTask(overrides: Partial<Task> = {}): Task {
  return {
    id: TASK_ID,
    title: "Test Task",
    repo: "my-repo",
    status: "in_review",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: `feature/${FEATURE_ID}-${TASK_ID}`,
    execution: { actor_type: "agent", last_updated_by: null, last_updated_at: null },
    pr: { url: "https://github.com/org/repo/pull/1", status: "open" },
    workspace_pr: null,
    log: [],
    ...overrides,
  };
}

function mockGitShow(task: Task): ReturnType<typeof spawnSync> {
  return {
    pid: 0, output: [], stdout: yamlStringify(task),
    stderr: "", status: 0, signal: null, error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

function mockPushSuccess(): ReturnType<typeof spawnSync> {
  return {
    pid: 0, output: [], stdout: "", stderr: "",
    status: 0, signal: null, error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

// ── Temp workspace helpers ────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspace(tasks: Task[], featureId = FEATURE_ID, mgmtGithub = MGMT_GITHUB): string {
  const wsDir = mkdtempSync(join(tmpdir(), "dispatch-ctrl-"));
  tmpDirs.push(wsDir);

  const tasksDir = join(wsDir, "docs", "features", featureId, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  for (const task of tasks) {
    writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");
  }

  writeFileSync(join(wsDir, "workspace.yaml"), yamlStringify({
    workspace_id: "test-ws",
    management_repo: "mgmt",
    repos: [
      { id: "mgmt", github: mgmtGithub },
      { id: "my-repo", github: "https://github.com/testorg/my-repo" },
    ],
  }), "utf-8");

  return wsDir;
}

function makeAgentConfig(watches = [MGMT_GITHUB]) {
  return {
    watches,
    budget: { max_tokens_per_task: 100000, max_iterations: 10 },
    idle_sleep_seconds: 0,
    max_concurrent_executors: 1,
    jitter_max_seconds: 0,
    log_sink: { enabled: false },
  };
}

afterEach(() => {
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
  vi.clearAllMocks();
  vi.resetModules();
});

// ── 1. dispatchReviewResult ───────────────────────────────────────────────────

describe("dispatchReviewResult — routing", () => {
  it("emits review_passed for passed status", async () => {
    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "passed", verdict: "approve", confidence: 0.9, notes: "LGTM" },
      workspaceRoot: "/fake",
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "review_passed")).toBe(true);
    expect(events.some((e) => e.type === "review_change_requested")).toBe(false);
  });

  it("emits review_escalate for escalate status", async () => {
    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "escalate", verdict: "escalate", confidence: 0.3, notes: "Too complex" },
      workspaceRoot: "/fake",
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "review_escalate")).toBe(true);
  });

  it("emits review_result_unknown_status for unknown status", async () => {
    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "what_is_this" as unknown as "passed", verdict: "?", confidence: 0, notes: "" },
      workspaceRoot: "/fake",
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "review_result_unknown_status")).toBe(true);
  });

  it("emits review_mutate_failed when mutation fails for change_requested", async () => {
    const { execSync, spawnSync: spMock } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "change_requested", verdict: "reject", confidence: 0.8, notes: "Fix the bug" },
      workspaceRoot: "/fake",
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "review_mutate_failed")).toBe(true);
    expect(events.some((e) => e.type === "review_change_requested")).toBe(false);
  });
});

// ── 2. findFixableTasks ───────────────────────────────────────────────────────

describe("findFixableTasks", () => {
  it("returns change_requested tasks with a PR URL", async () => {
    const task = makeTask({ status: "change_requested" });
    const wsDir = makeWorkspace([task]);
    vi.mocked(spawnSync).mockReturnValue(mockGitShow(task));

    const { findFixableTasks } = await import("../src/eligibility/match.js");
    const results = findFixableTasks(makeAgentConfig() as Parameters<typeof findFixableTasks>[0], wsDir);

    expect(results).toHaveLength(1);
    expect(results[0].task.id).toBe(TASK_ID);
  });

  it("skips change_requested tasks with no pr.url", async () => {
    const task = makeTask({ status: "change_requested", pr: { url: "", status: "open" } });
    const wsDir = makeWorkspace([task]);
    vi.mocked(spawnSync).mockReturnValue(mockGitShow(task));

    const { findFixableTasks } = await import("../src/eligibility/match.js");
    const results = findFixableTasks(makeAgentConfig() as Parameters<typeof findFixableTasks>[0], wsDir);

    expect(results).toHaveLength(0);
  });

  it("skips tasks that are not change_requested", async () => {
    const task = makeTask({ status: "in_review" });
    const wsDir = makeWorkspace([task]);

    const { findFixableTasks } = await import("../src/eligibility/match.js");
    const results = findFixableTasks(makeAgentConfig() as Parameters<typeof findFixableTasks>[0], wsDir);

    expect(results).toHaveLength(0);
    expect(vi.mocked(spawnSync)).not.toHaveBeenCalled();
  });

  it("returns empty when workspace is not watched", async () => {
    const task = makeTask({ status: "change_requested" });
    const wsDir = makeWorkspace([task]);

    const { findFixableTasks } = await import("../src/eligibility/match.js");
    const config = makeAgentConfig(["https://github.com/different/repo"]);
    const results = findFixableTasks(config as Parameters<typeof findFixableTasks>[0], wsDir);

    expect(results).toHaveLength(0);
    expect(vi.mocked(spawnSync)).not.toHaveBeenCalled();
  });

  it("skips when live branch status is no longer change_requested", async () => {
    const task = makeTask({ status: "change_requested" });
    const wsDir = makeWorkspace([task]);
    const liveTask = { ...task, status: "in_progress" as const };
    vi.mocked(spawnSync).mockReturnValue(mockGitShow(liveTask));

    const { findFixableTasks } = await import("../src/eligibility/match.js");
    const results = findFixableTasks(makeAgentConfig() as Parameters<typeof findFixableTasks>[0], wsDir);

    expect(results).toHaveLength(0);
  });
});

// ── 3. findReviewableTasks ────────────────────────────────────────────────────

describe("findReviewableTasks", () => {
  it("returns in_review tasks with a PR URL", async () => {
    const task = makeTask({ status: "in_review" });
    const wsDir = makeWorkspace([task]);
    vi.mocked(spawnSync).mockReturnValue(mockGitShow(task));

    const { findReviewableTasks } = await import("../src/eligibility/match.js");
    const results = findReviewableTasks(makeAgentConfig() as Parameters<typeof findReviewableTasks>[0], wsDir);

    expect(results).toHaveLength(1);
    expect(results[0].task.id).toBe(TASK_ID);
  });

  it("skips in_review tasks where last log action is reviewer_started", async () => {
    const task = makeTask({
      status: "in_review",
      log: [{ action: "reviewer_started", by: "bot@test.com", at: "2026-01-01T00:00:00Z" }],
    });
    const wsDir = makeWorkspace([task]);
    vi.mocked(spawnSync).mockReturnValue(mockGitShow(task));

    const { findReviewableTasks } = await import("../src/eligibility/match.js");
    const results = findReviewableTasks(makeAgentConfig() as Parameters<typeof findReviewableTasks>[0], wsDir);

    expect(results).toHaveLength(0);
  });

  it("skips in_review tasks with no pr.url", async () => {
    const task = makeTask({ status: "in_review", pr: { url: "", status: "open" } });
    const wsDir = makeWorkspace([task]);
    vi.mocked(spawnSync).mockReturnValue(mockGitShow(task));

    const { findReviewableTasks } = await import("../src/eligibility/match.js");
    const results = findReviewableTasks(makeAgentConfig() as Parameters<typeof findReviewableTasks>[0], wsDir);

    expect(results).toHaveLength(0);
  });

  it("skips tasks that are not in_review", async () => {
    const task = makeTask({ status: "change_requested" });
    const wsDir = makeWorkspace([task]);

    const { findReviewableTasks } = await import("../src/eligibility/match.js");
    const results = findReviewableTasks(makeAgentConfig() as Parameters<typeof findReviewableTasks>[0], wsDir);

    expect(results).toHaveLength(0);
    expect(vi.mocked(spawnSync)).not.toHaveBeenCalled();
  });

  it("returns empty when workspace is not watched", async () => {
    const task = makeTask({ status: "in_review" });
